window.docContents[42].resolve({"/rules/PL1002/#PL1002-proof-shape":{"contents":"The completed declaration keeps the same statement. Weakening the proposition until it is easy to prove changes the requirement and is a semantic review failure, even though this rule then passes.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1002: Proof holes are forbidden","header":"Required proof shape","id":"/rules/PL1002/#PL1002-proof-shape"},"/rules/PL2001/#PL2001-proof-shape":{"contents":"No proof obligation: the rule concerns the availability of the environment. The corrected run must then pass the applicable declaration and project rules.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2001: The declared Lean environment must be available","header":"Required proof shape","id":"/rules/PL2001/#PL2001-proof-shape"}});